import{_ as i,C as t,o,c as s,E as a,a2 as l}from"./chunks/framework.VWKgVqrc.js";const b=JSON.parse('{"title":"成品通过之前，先问哪些检查进入了分母","description":"","frontmatter":{"title":"成品通过之前，先问哪些检查进入了分母","date":"2026-11-07","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"评测中的成品通过是否意味着所有计划都已有成绩？它与运行停止、历史里程碑通过有何区别？","summary":"一个通过的计划加一个没有成绩的计划，仍可能得到成品通过；交付证据需要保留覆盖范围与漏项。","sources":"https://arxiv.org/html/2611.05620v1","pageClass":"runtime-v6-article","item_id":"SIG-20261107-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-07-sig-20261107-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-07-sig-20261107-005.md","filePath":"zh/engineering/2026-11-07-sig-20261107-005.md","lastUpdated":null}'),d={name:"zh/engineering/2026-11-07-sig-20261107-005.md"};function h(c,e,p,g,u,m){const r=t("ArticleCover"),n=t("ArticleTableScroll");return o(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-11-07-sig-20261107-005-cover.png",kicker:"研究成果",title:"成品通过之前，先问哪些检查进入了分母",summary:"一个通过的计划加一个没有成绩的计划，仍可能得到成品通过；交付证据需要保留覆盖范围与漏项。",version:"2026-11-07",languageHref:"/en/engineering/2026-11-07-sig-20261107-005",languageLabel:"English"}),a(n,{language:"zh"}),e[0]||(e[0]=l('<h1 id="成品通过之前-先问哪些检查进入了分母" tabindex="-1">成品通过之前，先问哪些检查进入了分母 <a class="header-anchor" href="#成品通过之前-先问哪些检查进入了分母" aria-label="Permalink to &quot;成品通过之前，先问哪些检查进入了分母&quot;">​</a></h1><p>一个检查计划通过，另一个计划没有任何已完成的评分，成品能否被计为通过？同日研究的合成文件探针在固定评分器中得到肯定答案，同时缺失计划仍被记录在审计字段中。这个结果没有改写任何模型的实测榜单，却说明“通过”必须连同检查范围一起解释。</p><p>对软件智能体的交付系统而言，运行已经停止、已计入的检查全通过、全部必需检查都有结果，是三个不同命题。如果交付记录只剩一个通过标记，接收者就无法分辨自己拿到的是哪一种证据。</p><h2 id="一张通过记录可能对应两种覆盖范围" tabindex="-1">一张通过记录可能对应两种覆盖范围 <a class="header-anchor" href="#一张通过记录可能对应两种覆盖范围" aria-label="Permalink to &quot;一张通过记录可能对应两种覆盖范围&quot;">​</a></h2><p>ViBench（网页产品智能体评测基准）的公开评分器按完整得分的严格多数判断计划通过。没有完成评分的计划进入缺失成绩字段，并从两种汇总分数中省略；初始化失败而没有成绩则按零分处理。纳入的计划没有失败项时，构建可记为通过。<a href="https://raw.githubusercontent.com/ViBench/vibench-public/main/harbor-adapter/src/vibench/score.py" target="_blank" rel="noreferrer">官方评分源码</a></p><p>内部实验没有运行网页产品或浏览器评分，而是向按内容哈希固定的评分器提供合成磁盘文件。一个计划通过、另一个计划无成绩时，成品通过值为真，分母中的计划数为 1，缺失列表保留第二项。两项都通过时，成品同样通过，但分母中的计划数为 2。相同的通过值因此不代表相同的覆盖完整性。</p><table tabindex="0"><thead><tr><th>合成用例</th><th>内部实验输出</th><th>解释边界</th></tr></thead><tbody><tr><td>一个通过、一个无成绩</td><td>成品通过，纳入 1 项，保留缺失项</td><td>通过已纳入的检查</td></tr><tr><td>两项均通过</td><td>成品通过，纳入 2 项</td><td>两项检查均有通过成绩</td></tr><tr><td>第二项初始化失败</td><td>成品失败，计划通过率为一半</td><td>初始化失败不能当作普通无成绩</td></tr><tr><td>第二项评分平票</td><td>成品失败</td><td>严格多数并非不低于半数</td></tr><tr><td>两项均无成绩</td><td>返回空值</td><td>没有可用分母，不是零分</td></tr><tr><td>两项成绩数均不足门槛</td><td>返回空值，保留排除原因</td><td>评分数量要求独立于已有分值</td></tr></tbody></table><p>全部表格结果均为内部实验依据，输入和实际输出见<a href="/joinwell52/assets/evidence/2026-11-07-sig-20261107-005/denominator-experiment.json">评分器用例记录</a>。实验沿用原评分逻辑，以替身处理包级计划发现、来源信息及未使用的成本采集；它没有执行真实构建、封闭评分模型或留出产品。不能从这组文件推断完整基准存在漏洞，也不能据此修正论文分数。</p><h2 id="历史每步通过与最终成品通过不回答同一问题" tabindex="-1">历史每步通过与最终成品通过不回答同一问题 <a class="header-anchor" href="#历史每步通过与最终成品通过不回答同一问题" aria-label="Permalink to &quot;历史每步通过与最终成品通过不回答同一问题&quot;">​</a></h2><p>Multi-step SWE（多步骤软件工程评测）要求历史步骤都达到满分，最终修好不能抹掉先前失败。来源报告最强模型与执行框架组合有 56.8% 的步骤通过，完整序列解决率为 18.5%，后者的置信区间为 11.6%—25.7%。这些是不同事件的比例，不是同一分数在两种表述下的矛盾。<a href="https://arxiv.org/html/2611.07166v1" target="_blank" rel="noreferrer">论文，第 3—5 节</a></p><p>ViBench 评估最终产物，作者报告一个模型的计划通过率为 96.9%，完整产品通过率为 64.7%；另一模型分别为 98.0% 与 60.3%。最终修复能够影响最终成品检查，而历史每步成功合同仍会保留先前失败。计划数、验收时间和缺失处理不同，不能据这些数字直接排名两套基准的难度或系统优劣。<a href="https://arxiv.org/html/2611.05620v1" target="_blank" rel="noreferrer">论文，第 2—4 节</a></p><p>代表性的多步骤任务清单使用步骤奖励平均值作为试验奖励，这又不等于论文中的全步骤解决率。其验证包装脚本检查权限隔离、重新构建并校验测试完整性，但研究只检查了一个代表性包装脚本，未审计被调用的全部辅助与评分实现。<a href="https://raw.githubusercontent.com/Klavis-AI/Multi-step-SWE/main/tasks/lua-vm-version-chain/task.toml" target="_blank" rel="noreferrer">官方任务清单</a>，<a href="https://raw.githubusercontent.com/Klavis-AI/Multi-step-SWE/main/tasks/lua-vm-version-chain/steps/01-lua-5-1/tests/test.sh" target="_blank" rel="noreferrer">验证包装脚本</a></p><h2 id="停下来的系统还没有自动取得外部验收" tabindex="-1">停下来的系统还没有自动取得外部验收 <a class="header-anchor" href="#停下来的系统还没有自动取得外部验收" aria-label="Permalink to &quot;停下来的系统还没有自动取得外部验收&quot;">​</a></h2><p>MetaGPT（多智能体软件协作框架）中被检查的团队运行方法，会在空闲或轮数耗尽时停止，并归档、返回历史；基础环境的空闲条件是所有角色都空闲。它们描述运行状态，不是对交付产物正确性的外部判定。<a href="https://raw.githubusercontent.com/FoundationAgents/MetaGPT/main/metagpt/team.py" target="_blank" rel="noreferrer">团队运行源码</a>，<a href="https://raw.githubusercontent.com/FoundationAgents/MetaGPT/main/metagpt/environment/base_env.py" target="_blank" rel="noreferrer">基础环境源码</a></p><p>这不是“整个框架没有验证器”的证据：其他路径可能存在验证，默认扩展环境的重载行为也未在本研究中检查。比较的有效范围是三个被检查的判断层次：历史过程合同、最终产物验收、运行停止谓词。只有先写明所问的问题，才能解释一个完成标记。</p><p>我们的工程解释是，交付记录应绑定验收合同、实际产物与评分器版本，并分别保留运行结束、纳入检查、必需检查完成情况、失败项与排除项。如果合同要求每项必需检查有结果，就应额外验证覆盖完整性；这项建议尚未通过部署实验，不意味着评分器不会犯错。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>论文的模型分数属于来源陈述；公开评分器与停止方法属于被检查的实现事实；六组文件结果属于内部实验依据。独立的验收进程与独立第三方复现是不同概念：本研究没有独立复现两套基准，也没有运行真实产品测试。发表、引用和源码可见性不能代替结果验证。</p><p>主要来源为 <a href="https://arxiv.org/html/2611.07166v1" target="_blank" rel="noreferrer">arXiv（开放研究预印本平台）多步骤软件工程预印本 2611.07166，第一版</a>、<a href="https://arxiv.org/html/2611.05620v1" target="_blank" rel="noreferrer">网页产品评测预印本 2611.05620，第一版</a>，以及上文相邻列出的官方源码。所有实现观察限于本次研究固定的内容快照，当前分支快照并非已确认的论文发布提交。网页产品基准有 9 个留出产品、仅 8 个公开产品可供复现，不能把公开评分器探针当成完整覆盖。</p><h2 id="尚未回答的是漏项何时影响实际结论" tabindex="-1">尚未回答的是漏项何时影响实际结论 <a class="header-anchor" href="#尚未回答的是漏项何时影响实际结论" aria-label="Permalink to &quot;尚未回答的是漏项何时影响实际结论&quot;">​</a></h2><p>无成绩如何形成、实际构建中出现多少次、是否改变模型排序，本研究没有测量。论文称其检查的独立构建没有因相关漏项而改变首次通过结果，本文未重新计算。下一步需要的是逐构建的必需计划清单、完成记录、排除原因与固定评分版本，才能判断一次“通过”究竟覆盖了多少交付责任。</p>',21))])}const f=i(d,[["render",h]]);export{b as __pageData,f as default};
